import{lookThrough}from'./research-math.84c2affbee23.js';
const data=document.getElementById('lookthrough-data');
if(data){const funds=JSON.parse(data.textContent),inputs=[...document.querySelectorAll('[data-allocation]')],amount=document.getElementById('portfolio-amount'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),pct=n=>n.toFixed(2)+'%',money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
 const calculate=()=>{const allocations=Object.fromEntries(inputs.map(i=>[i.dataset.allocation,i.value.trim()===''?0:Number(i.value)])),r=lookThrough(funds,allocations,Number(amount.value));document.getElementById('allocation-total').textContent=(Number.isFinite(r.total)?r.total.toFixed(2):'--')+'% allocated';const error=document.getElementById('allocation-error');error.textContent=r.ok?'':r.errors.join(' ');document.getElementById('exposure-output').hidden=!r.ok;if(!r.ok)return;document.getElementById('coverage-known').textContent=pct(r.known);document.getElementById('coverage-unmapped').textContent=pct(r.unmapped);document.getElementById('issuer-results').innerHTML=r.issuers.length?r.issuers.map(i=>`<tr><th scope="row"><a href="/holdings/${encodeURIComponent(i.key)}/">${esc(i.name)}</a></th><td>${pct(i.weight)}</td><td>${money(i.dollars)}</td><td>${i.funds.map(f=>`${esc(f.fundId.toUpperCase())}: ${pct(f.contribution)} <span class="muted">(${esc(f.baselineDate||'date unavailable')})</span>`).join('<br>')}</td></tr>`).join(''):'<tr><td colspan="4">No holdings coverage for the selected funds. The allocation is shown as unmapped.</td></tr>';document.getElementById('sector-results').innerHTML=r.sectors.map(s=>`<li><span>${esc(s.name)}</span><strong>${pct(s.weight)}</strong></li>`).join('');};inputs.forEach(i=>i.addEventListener('input',calculate));amount.addEventListener('input',calculate);document.getElementById('equal-covered').addEventListener('click',()=>{const covered=funds.filter(f=>f.holdingsReport?.holdings?.length);inputs.forEach(i=>i.value=covered.some(f=>f.id===i.dataset.allocation)?(100/covered.length).toFixed(4):0);calculate();});document.getElementById('reset-allocations').addEventListener('click',()=>{inputs.forEach(i=>i.value=0);calculate();});calculate();}
const month=document.getElementById('calendar-month');if(month)month.addEventListener('change',()=>{for(const card of document.querySelectorAll('[data-event-month]'))card.hidden=!!month.value&&card.dataset.eventMonth!==month.value;});
